// Generated by make-slides.py: slide order, trainer-only slides, section starts.
const SLIDES = [
  "index.html",
  "p1-00-part.html",
  "p1-01-believe.html",
  "p1-05-lateral.html",
  "p1-06-demo.html",
  "p1-07-sift.html",
  "p1-08-image.html",
  "p1-09-ai.html",
  "p1-10-race.html",
  "p1-12-take.html",
  "p2-00-part.html",
  "p2-01-confirmation.html",
  "p2-02-headlines.html",
  "p2-03-five.html",
  "p2-04-toolkit.html",
  "p2-06-six.html",
  "p2-07-gallery.html",
  "p2-08-honest.html",
  "p2-09-take.html"
];
const TRAINER_ONLY = [];
const SECTIONS = ["p1-00-part.html", "p2-00-part.html"];

// Navigation (appended to nav.js by make-slides.py). Footer = column rules, one per slide; red rules start a part.
window.FTSFoot = function (foot, i, N, hrefOf, isStart, onPick) {
  const pad = (n) => String(n).padStart(2, "0");
  let cols = "";
  for (let n = 0; n < N; n++) {
    const cls = [n < i ? "done" : "", n === i ? "cur" : "", isStart(n) ? "sec" : ""].join(" ").trim();
    cols += `<a href="${hrefOf(n)}" class="${cls}" aria-label="Slide ${n + 1}"${n === i ? ' aria-current="true"' : ""}></a>`;
  }
  foot.innerHTML =
    `<a href="${i > 0 ? hrefOf(i - 1) : "#"}" aria-disabled="${i <= 0}">← Back</a>` +
    `<div class="cols-nav">${cols}</div>` +
    `<span class="pg">p. ${pad(i + 1)} / ${pad(N)}</span>` +
    `<a href="${i < N - 1 ? hrefOf(i + 1) : "#"}" aria-disabled="${i >= N - 1}">Next →</a>`;
  if (onPick) {
    foot.addEventListener("click", (e) => {
      const a = e.target.closest("a");
      if (!a) return;
      e.preventDefault(); e.stopPropagation();
      if (a.getAttribute("aria-disabled") === "true") return;
      const list = Array.from(foot.querySelectorAll("a"));
      const k = list.indexOf(a);
      if (k === 0) onPick(i - 1, true);
      else if (k === list.length - 1) onPick(i + 1, false);
      else onPick(k - 1, false);
    });
  }
};

if (!window.FTS_BUNDLE) (function () {
  let file = location.pathname.split("/").pop() || "index.html";
  if (!file.endsWith(".html")) file += ".html";
  const i = Math.max(0, SLIDES.indexOf(file));
  const N = SLIDES.length;
  const foot = document.querySelector(".foot");
  if (foot) window.FTSFoot(foot, i, N, (n) => SLIDES[n], (n) => SECTIONS.includes(SLIDES[n]));

  const steps = Array.from(document.querySelectorAll(".reveal"));
  let shown = 0;
  function forward() {
    if (shown < steps.length) { steps[shown++].classList.add("on"); return; }
    if (i < N - 1) location.href = SLIDES[i + 1];
  }
  function back() {
    if (shown > 0) { steps[--shown].classList.remove("on"); return; }
    if (i > 0) location.href = SLIDES[i - 1];
  }
  const noteText = Array.from(document.body.childNodes).find((n) => n.nodeType === 8)?.textContent.trim();
  const note = document.createElement("aside");
  note.className = "note";
  note.textContent = noteText || "";
  document.body.appendChild(note);

  document.addEventListener("keydown", (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    const k = e.key.toLowerCase();
    if (k === "n") { document.body.classList.toggle("notes"); return; }
    if (k === "f") {
      if (document.fullscreenElement) document.exitFullscreen?.();
      else document.documentElement.requestFullscreen?.().catch(() => {});
      return;
    }
    if (e.key === "Home") location.href = SLIDES[0];
    if (e.key === "End") location.href = SLIDES[N - 1];
    if (["ArrowRight", "PageDown", " ", "Enter"].includes(e.key)) { e.preventDefault(); forward(); }
    if (["ArrowLeft", "PageUp", "Backspace"].includes(e.key)) { e.preventDefault(); back(); }
  });
  document.querySelector(".content")?.addEventListener("click", forward);
})();
